  "-- Gebya platform-admin toolkit migration\n-- Support tickets + messages, admin shop logs, owner Telegram link token.\n-- Cleaned for the Supabase SQL editor (no drizzle breakpoint comments; idempotent).\n\nCREATE TABLE IF NOT EXISTS \"support_tickets\" (\n  \"id\" serial PRIMARY KEY NOT NULL,\n  \"business_id\" integer NOT NULL,\n  \"owner_user_id\" integer NOT NULL,\n  \"subject\" varchar(255) NOT NULL,\n  \"description\" text NOT NULL,\n  \"status\" varchar(32) DEFAULT 'open' NOT NULL,\n  \"priority\" varchar(16) DEFAULT 'normal' NOT NULL,\n  \"created_at\" timestamptz DEFAULT now(),\n  \"updated_at\" timestamptz DEFAULT now(),\n  \"resolved_at\" timestamptz,\n  \"resolved_by_user_id\" integer\n);\n\nCREATE TABLE IF NOT EXISTS \"support_messages\" (\n  \"id\" serial PRIMARY KEY NOT NULL,\n  \"ticket_id\" integer NOT NULL,\n  \"sender_user_id\" integer NOT NULL,\n  \"sender_role\" varchar(32) NOT NULL,\n  \"body\" text NOT NULL,\n  \"created_at\" timestamptz DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS \"admin_shop_logs\" (\n  \"id\" serial PRIMARY KEY NOT NULL,\n  \"business_id\" integer NOT NULL,\n  \"admin_phone\" varchar(32),\n  \"type\" varchar(32) NOT NULL,\n  \"channel\" varchar(32),\n  \"title\" varchar(200),\n  \"body\" text,\n  \"status\" varchar(32),\n  \"created_at\" timestamp DEFAULT now() NOT NULL\n);\n\nALTER TABLE \"users\" ADD COLUMN IF NOT EXISTS \"telegram_link_token\" text;\n\nCREATE INDEX IF NOT EXISTS \"support_tickets_business_idx\" ON \"support_tickets\" USING btree (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"support_tickets_status_idx\" ON \"support_tickets\" USING btree (\"status\");\nCREATE INDEX IF NOT EXISTS \"support_messages_ticket_idx\" ON \"support_messages\" USING btree (\"ticket_id\");\nCREATE INDEX IF NOT EXISTS \"admin_shop_logs_business_idx\" ON \"admin_shop_logs\" USING btree (\"business_id\");\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'support_messages_ticket_id_support_tickets_id_fk') THEN\n    ALTER TABLE \"support_messages\" ADD CONSTRAINT \"support_messages_ticket_id_support_tickets_id_fk\"\n      FOREIGN KEY (\"ticket_id\") REFERENCES \"public\".\"support_tickets\"(\"id\") ON DELETE cascade ON UPDATE no action;\n  END IF;\nEND $$;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'support_tickets_business_id_businesses_id_fk') THEN\n    ALTER TABLE \"support_tickets\" ADD CONSTRAINT \"support_tickets_business_id_businesses_id_fk\"\n      FOREIGN KEY (\"business_id\") REFERENCES \"public\".\"businesses\"(\"id\") ON DELETE cascade ON UPDATE no action;\n  END IF;\nEND $$;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'support_tickets_owner_user_id_users_id_fk') THEN\n    ALTER TABLE \"support_tickets\" ADD CONSTRAINT \"support_tickets_owner_user_id_users_id_fk\"\n      FOREIGN KEY (\"owner_user_id\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE cascade ON UPDATE no action;\n  END IF;\nEND $$;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'admin_shop_logs_business_id_businesses_id_fk') THEN\n    ALTER TABLE \"admin_shop_logs\" ADD CONSTRAINT \"admin_shop_logs_business_id_businesses_id_fk\"\n      FOREIGN KEY (\"business_id\") REFERENCES \"public\".\"businesses\"(\"id\") ON DELETE cascade ON UPDATE no action;\n  END IF;\nEND $$;\n",
  "-- Phase 2: Premium tier gating for automated reminders\n-- Adds a `plan` column to businesses to distinguish free vs premium shops.\n-- Automated (cron-triggered) reminders are gated behind plan = 'premium'.\n-- On-demand (manual) reminders work for all plans.\n\nALTER TABLE \"businesses\" ADD COLUMN IF NOT EXISTS \"plan\" varchar(32) NOT NULL DEFAULT 'free';\n",
  "-- Gebya platform-admin team members (dynamic allowlist).\n-- The server also auto-creates this table on boot via ensureSchema; this file\n-- is provided for manual application (e.g., Supabase SQL editor) if needed.\n-- Clean and idempotent.\n\nCREATE TABLE IF NOT EXISTS \"platform_admin_members\" (\n  \"id\" serial PRIMARY KEY NOT NULL,\n  \"phone\" text NOT NULL,\n  \"added_by_phone\" text,\n  \"note\" text,\n  \"created_at\" timestamp DEFAULT now() NOT NULL\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS \"platform_admin_members_phone_unique\" ON \"platform_admin_members\" USING btree (\"phone\");",
  "-- Run this in Supabase SQL Editor\r\n-- Creates the notifications + push_subscriptions tables\r\n-- Safe to run even if other tables don't exist yet\r\n\r\nCREATE TABLE IF NOT EXISTS \"notifications\" (\r\n  \"id\" serial PRIMARY KEY NOT NULL,\r\n  \"business_id\" integer NOT NULL,\r\n  \"owner_user_id\" integer NOT NULL,\r\n  \"type\" varchar(64) NOT NULL,\r\n  \"title\" varchar(255) NOT NULL,\r\n  \"body\" text NOT NULL,\r\n  \"entity_type\" varchar(64),\r\n  \"entity_id\" varchar(128),\r\n  \"actor_name\" varchar(128),\r\n  \"amount\" numeric(12, 2),\r\n  \"read\" boolean DEFAULT false NOT NULL,\r\n  \"created_at\" timestamp with time zone DEFAULT now()\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS \"push_subscriptions\" (\r\n  \"id\" serial PRIMARY KEY NOT NULL,\r\n  \"user_id\" integer NOT NULL,\r\n  \"business_id\" integer NOT NULL,\r\n  \"endpoint\" text NOT NULL,\r\n  \"p256dh\" text NOT NULL,\r\n  \"auth\" text NOT NULL,\r\n  \"user_agent\" text,\r\n  \"created_at\" timestamp with time zone DEFAULT now()\r\n);\r\n\r\n-- Indexes\r\nCREATE INDEX IF NOT EXISTS \"notif_biz_owner_idx\" ON \"notifications\" USING btree (\"business_id\",\"owner_user_id\",\"created_at\");\r\nCREATE INDEX IF NOT EXISTS \"notif_unread_idx\" ON \"notifications\" USING btree (\"business_id\",\"owner_user_id\",\"read\");\r\nCREATE UNIQUE INDEX IF NOT EXISTS \"push_sub_endpoint_idx\" ON \"push_subscriptions\" USING btree (\"endpoint\");\r\nCREATE INDEX IF NOT EXISTS \"push_sub_user_idx\" ON \"push_subscriptions\" USING btree (\"user_id\");\r\nCREATE INDEX IF NOT EXISTS \"push_sub_biz_idx\" ON \"push_subscriptions\" USING btree (\"business_id\");\r\n",
  "-- Migration: Add password authentication columns to users table\n-- Run this in Supabase SQL Editor\n-- Safe to run — all new columns are nullable\n\nALTER TABLE \"users\"\n  ADD COLUMN IF NOT EXISTS \"password_hash\" text,\n  ADD COLUMN IF NOT EXISTS \"password_set_at\" timestamp with time zone,\n  ADD COLUMN IF NOT EXISTS \"password_attempts\" integer DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS \"password_locked_until\" timestamp with time zone;\n"
